def parse_spec(spec):
    """`name` or `name:arg` into (function, arg); the argument is everything after the first colon."""
    name, _, arg = spec.partition(":")
    if name not in TRANSFORMS:
        raise TabulaError("unknown transform %r" % name)
    return TRANSFORMS[name], (arg if ":" in spec else None)


def apply_transforms(value, specs):
    for fn, arg in specs:
        value = fn(value, arg)
    return value


# --- commands ------------------------------------------------------------------------------------------------

def _need_args(args, count, usage):
    if len(args) != count:
        raise UsageError("usage: %s %s" % (PROG, usage))


def cmd_show(args, opts):
    _need_args(args, 1, "show FILE")
    return load(args[0])


def cmd_head(args, opts):
    _need_args(args, 2, "head FILE N")
    if not args[1].isdigit():
        raise UsageError("head: N must be a whole number, got %r" % args[1])
    table = load(args[0])
    return table.with_rows(table.rows[:int(args[1])])


def cmd_cols(args, opts):
    _need_args(args, 1, "cols FILE")
    table = load(args[0])
    return Table(["position", "column"], [[str(i + 1), name] for i, name in enumerate(table.columns)], table.source)


def cmd_apply(args, opts):
    if len(args) < 3:
        raise UsageError("usage: %s apply FILE COLUMN TRANSFORM..." % PROG)
    table = load(args[0])
    at = table.index(args[1])
    specs = [parse_spec(s) for s in args[2:]]
    rows = []
    for number, row in enumerate(table.rows, 1):
        row = list(row)
        try:
            row[at] = apply_transforms(row[at], specs)
        except TabulaError as exc:
            raise TabulaError("%s: row %d: %s" % (table.source, number, exc))
        rows.append(row)
    return table.with_rows(rows)


def _need_min_args(args, count, usage):
    if len(args) < count:
        raise UsageError("usage: %s %s" % (PROG, usage))


SORT_MODIFIERS = ("num", "desc")


def _sort_key(spec):
    """`COLUMN[:num][:desc]` into (column, numeric, descending)."""
    name, *modifiers = spec.split(":")
    if not name:
        raise UsageError("sort: no column name in %r" % spec)
    for modifier in modifiers:
        if modifier not in SORT_MODIFIERS:
            raise UsageError("sort: unknown modifier %r in %r (use num or desc)" % (modifier, spec))
    if len(set(modifiers)) != len(modifiers):
        raise UsageError("sort: a modifier is given twice in %r" % spec)
    return name, "num" in modifiers, "desc" in modifiers


def cmd_sort(args, opts):
    _need_min_args(args, 2, "sort FILE KEY...")
    keys = [_sort_key(spec) for spec in args[1:]]
    table = load(args[0])
    keys = [(table.index(name), numeric, desc) for name, numeric, desc in keys]
    values = [[cell_number(table, n, at) if numeric else row[at] for at, numeric, _ in keys]
              for n, row in enumerate(table.rows)]
    order = list(range(len(table.rows)))
    for k in range(len(keys) - 1, -1, -1):  # one stable sort per key, the last key first
        order.sort(key=lambda n: values[n][k], reverse=keys[k][2])
    return table.with_rows([table.rows[n] for n in order])


# longest first, so that where two operators start at the same place the longer one wins
FILTER_OPERATORS = ("==", "!=", ">=", "<=", ">", "<", "~")


def _condition(arg):
    """`COLUMN OP VALUE` into (column, operator, value): the first operator in the argument, the longer at a tie."""
    for at in range(len(arg)):
        for op in FILTER_OPERATORS:
            if arg.startswith(op, at):
                if at == 0:
                    raise UsageError("filter: no column name in %r" % arg)
                return arg[:at], op, arg[at + len(op):]
    raise UsageError("filter: no operator (== != >= <= > < ~) in %r" % arg)


def _holds(cell, op, value, number):
    if op == "~":
        return value.lower() in cell.lower()
    left = to_decimal(cell) if number is not None else None
    if left is not None:
        cell, value = left, number
    return {"==": cell == value, "!=": cell != value, ">=": cell >= value, "<=": cell <= value,
            ">": cell > value, "<": cell < value}[op]


def cmd_filter(args, opts):
    _need_min_args(args, 2, "filter FILE CONDITION...")
    conditions = [_condition(arg) for arg in args[1:]]
    table = load(args[0])
    conditions = [(table.index(name), op, value, to_decimal(value)) for name, op, value in conditions]
    return table.with_rows([row for row in table.rows
                            if all(_holds(row[at], op, value, number) for at, op, value, number in conditions)])


AGGREGATES = ("sum", "min", "max", "mean")


def _aggregate(spec):
    """`count` or `KIND:COLUMN` into (kind, column or None)."""
    kind, colon, column = spec.partition(":")
    if spec == "count":
        return kind, None
    if kind not in AGGREGATES or not colon or not column:
        raise UsageError("group: %r is not an aggregate (count, sum:COLUMN, min:COLUMN, max:COLUMN, mean:COLUMN)" % spec)
    return kind, column


def _unique_columns(columns, source):
    for name in columns:
        if columns.count(name) > 1:
            raise TabulaError("%s: the result would have the column %r twice" % (source, name))
    return columns


def cmd_group(args, opts):
    _need_min_args(args, 3, "group FILE BY AGGREGATE...")
    if len(set(args[2:])) != len(args[2:]):
        raise UsageError("group: an aggregate is given twice")
    aggregates = [_aggregate(spec) for spec in args[2:]]
    table = load(args[0])
    by = table.index(args[1])
    columns = [None if column is None else table.index(column) for _, column in aggregates]
    groups = {}  # value of BY -> row numbers, in the order each value first appears
    for n, row in enumerate(table.rows):
        groups.setdefault(row[by], []).append(n)
    wanted = sorted(set(columns) - {None})
    numbers = {at: [] for at in wanted}  # row by row, so the first bad cell in file order is the one reported
    for n in range(len(table.rows)):
        for at in wanted:
            numbers[at].append(cell_number(table, n, at))
    rows = []
    for value, members in groups.items():
        out = [value]
        for (kind, _), at in zip(aggregates, columns):
            if kind == "count":
                out.append(str(len(members)))
                continue
            found = [numbers[at][n] for n in members]
            if kind == "sum":
                out.append(fmt_decimal(exact_sum(found)))
            elif kind == "mean":
                out.append(fmt_2dp(exact_sum(found), len(found)))
            else:
                out.append(fmt_decimal((min if kind == "min" else max)(found)))
        rows.append(out)
    names = [args[1]] + [spec.replace(":", "_") for spec in args[2:]]
    return Table(_unique_columns(names, table.source), rows, table.source)


def cmd_join(args, opts):
    _need_args(args, 3, "join LEFT RIGHT KEY")
    left, right = load(args[0]), load(args[1])
    at_left, at_right = left.index(args[2]), right.index(args[2])
    kept = [i for i in range(len(right.columns)) if i != at_right]
    columns = left.columns + [right.columns[i] + "_right" if right.columns[i] in left.columns else right.columns[i]
                              for i in kept]
    matches = {}
    for row in right.rows:
        matches.setdefault(row[at_right], []).append([row[i] for i in kept])
    rows = []
    for row in left.rows:
        found = matches.get(row[at_left])
        if found:
            rows.extend(row + other for other in found)
        elif opts["kind"] == "left":
            rows.append(row + [""] * len(kept))
    return Table(_unique_columns(columns, left.source), rows, left.source)


def cmd_pivot(args, opts):
    _need_args(args, 4, "pivot FILE ROW COLUMN VALUE")
    if args[1] == args[2]:
        raise UsageError("pivot: ROW and COLUMN must be different columns, got %r twice" % args[1])
    table = load(args[0])
    at_row, at_col, at_value = table.index(args[1]), table.index(args[2]), table.index(args[3])
    heads, rows, sums = {}, {}, {}  # distinct COLUMN values and ROW values (first appearance order), the sums
    for n, row in enumerate(table.rows):
        head = row[at_col]
        if not head:
            raise TabulaError("%s: row %d: column %r: empty value" % (table.source, n + 1, args[2]))
        if head == args[1]:
            raise TabulaError("%s: row %d: column %r: %r is the name of the ROW column" % (table.source, n + 1, args[2], head))
        number = cell_number(table, n, at_value)
        heads[head] = rows[row[at_row]] = None
        key = (row[at_row], head)
        sums[key] = number if key not in sums else EXACT.add(sums[key], number)
    return Table([args[1]] + list(heads),
                 [[value] + [fmt_decimal(sums[(value, head)]) if (value, head) in sums else "0" for head in heads]
                  for value in rows], table.source)


def cmd_dedupe(args, opts):
    _need_min_args(args, 2, "dedupe FILE KEY...")
    table = load(args[0])
    keys = [table.index(name) for name in args[1:]]
    chosen = {}  # the values of the KEY columns -> the number of the row that stays
    for n, row in enumerate(table.rows):
        key = tuple(row[at] for at in keys)
        if opts["keep"] == "last" or key not in chosen:
            chosen[key] = n
    stay = set(chosen.values())
    return table.with_rows([row for n, row in enumerate(table.rows) if n in stay])


def cmd_stats(args, opts):
    _need_min_args(args, 2, "stats FILE COLUMN...")
    table = load(args[0])
    rows = []
    for name in args[1:]:
