    if len(args) < count:
        raise UsageError("usage: %s %s" % (PROG, usage))


SORT_MODIFIERS = ("num", "desc")


def _sort_key(spec):
    """`COLUMN[:num][:desc]` into (column, numeric, descending)."""
    name, *modifiers = spec.split(":")
    if not name:
        raise UsageError("sort: no column name in %r" % spec)
    for modifier in modifiers:
        if modifier not in SORT_MODIFIERS:
            raise UsageError("sort: unknown modifier %r in %r (use num or desc)" % (modifier, spec))
    if len(set(modifiers)) != len(modifiers):
        raise UsageError("sort: a modifier is given twice in %r" % spec)
    return name, "num" in modifiers, "desc" in modifiers


def cmd_sort(args, opts):
    _need_min_args(args, 2, "sort FILE KEY...")
    keys = [_sort_key(spec) for spec in args[1:]]
    table = load(args[0])
    keys = [(table.index(name), numeric, desc) for name, numeric, desc in keys]
    values = [[cell_number(table, n, at) if numeric else row[at] for at, numeric, _ in keys]
              for n, row in enumerate(table.rows)]
    order = list(range(len(table.rows)))
    for k in range(len(keys) - 1, -1, -1):  # one stable sort per key, the last key first
        order.sort(key=lambda n: values[n][k], reverse=keys[k][2])
    return table.with_rows([table.rows[n] for n in order])


# longest first, so that where two operators start at the same place the longer one wins
FILTER_OPERATORS = ("==", "!=", ">=", "<=", ">", "<", "~")


def _condition(arg):
    """`COLUMN OP VALUE` into (column, operator, value): the first operator in the argument, the longer at a tie."""
    for at in range(len(arg)):
        for op in FILTER_OPERATORS:
            if arg.startswith(op, at):
                if at == 0:
                    raise UsageError("filter: no column name in %r" % arg)
                return arg[:at], op, arg[at + len(op):]
    raise UsageError("filter: no operator (== != >= <= > < ~) in %r" % arg)


def _holds(cell, op, value, number):
    if op == "~":
        return value.lower() in cell.lower()
    left = to_decimal(cell) if number is not None else None
    if left is not None:
        cell, value = left, number
    return {"==": cell == value, "!=": cell != value, ">=": cell >= value, "<=": cell <= value,
            ">": cell > value, "<": cell < value}[op]


def cmd_filter(args, opts):
    _need_min_args(args, 2, "filter FILE CONDITION...")
    conditions = [_condition(arg) for arg in args[1:]]
    table = load(args[0])
    conditions = [(table.index(name), op, value, to_decimal(value)) for name, op, value in conditions]
    return table.with_rows([row for row in table.rows
