def cmd_join(args, opts):
    _need_args(args, 3, "join LEFT RIGHT KEY")
    left, right = load(args[0]), load(args[1])
    at_left, at_right = left.index(args[2]), right.index(args[2])
    kept = [i for i in range(len(right.columns)) if i != at_right]
    columns = left.columns + [right.columns[i] + "_right" if right.columns[i] in left.columns else right.columns[i]
                              for i in kept]
    matches = {}
    for row in right.rows:
        matches.setdefault(row[at_right], []).append([row[i] for i in kept])
    rows = []
    for row in left.rows:
        found = matches.get(row[at_left])
        if found:
            rows.extend(row + other for other in found)
        elif opts["kind"] == "left":
            rows.append(row + [""] * len(kept))
    return Table(_unique_columns(columns, left.source), rows, left.source)


def cmd_pivot(args, opts):
    _need_args(args, 4, "pivot FILE ROW COLUMN VALUE")
    if args[1] == args[2]:
        raise UsageError("pivot: ROW and COLUMN must be different columns, got %r twice" % args[1])
    table = load(args[0])
    at_row, at_col, at_value = table.index(args[1]), table.index(args[2]), table.index(args[3])
    heads, rows, sums = {}, {}, {}  # distinct COLUMN values and ROW values (first appearance order), the sums
    for n, row in enumerate(table.rows):
