"""tabula.engine -- the table model, the transforms, the output formats and the command line.

This is the one module every command lives in. A command is a function `cmd_NAME(args, opts)` that gets the
positional arguments (a list of strings) and the options (a dict) and returns a Table, which `main` then prints in the
format asked for (`--format text|csv|json`, text by default). A mistake in a file or in a request raises TabulaError
(exit status 1); a command line that is not shaped right raises UsageError (exit status 2).
"""
import csv
import io
import json
import os
import re
import sys
import unicodedata
from decimal import (Context, Decimal, InvalidOperation, MAX_EMAX, MAX_PREC, MIN_EMIN, ROUND_HALF_UP, ROUND_FLOOR,
                     ROUND_CEILING, ROUND_DOWN, getcontext)
from fractions import Fraction

from .errors import TabulaError, UsageError

PROG = "tabula"
FORMATS = ("text", "csv", "json")
# The options of the command line: name -> (allowed values, default). `parse_args` reads all of them the same way.
OPTIONS = {
    "format": (FORMATS, "text"),
    "kind": (("inner", "left"), "inner"),
    "keep": (("first", "last"), "first"),
}
getcontext().prec = 60
EXACT = Context(prec=MAX_PREC, Emax=MAX_EMAX, Emin=MIN_EMIN)  # sums of any length lose no digit

NUMBER = re.compile(r"[+-]?(?:\d+(?:\.\d*)?|\.\d+)")


# --- numbers -------------------------------------------------------------------------------------------------

def to_decimal(text):
    """The Decimal a cell holds, or None when it is not a plain decimal number (no exponent, no thousands marks)."""
    text = text.strip()
    if not NUMBER.fullmatch(text):
        return None
    try:
        return Decimal(text)
    except InvalidOperation:
        return None


def fmt_decimal(number):
    """A Decimal as plain text: no exponent, no negative zero."""
    text = format(number, "f")
    if text.startswith("-") and not text.strip("-0."):
        text = text[1:]
    return text


def _need_number(value):
    number = to_decimal(value)
    if number is None:
        raise TabulaError("%r is not a number" % value)
    return number


def cell_number(table, row, at):
    """The Decimal in data row `row` (counted from 0, in file order) of column number `at`; TabulaError if not a number."""
    value = table.rows[row][at]
    number = to_decimal(value)
    if number is None:
        raise TabulaError("%s: row %d: column %r: %r is not a number" % (table.source, row + 1, table.columns[at], value))
    return number


def exact_sum(numbers):
    """The exact sum of Decimals (the default context would round it)."""
    total = Decimal(0)
    for number in numbers:
        total = EXACT.add(total, number)
    return total


def fmt_2dp(total, count=1):
    """`total / count` rounded half up (away from zero on a tie) to two decimals, always printed with two."""
    scaled = Fraction(total) * 100 / count
    cents = (2 * abs(scaled.numerator) + scaled.denominator) // (2 * scaled.denominator)
    return fmt_decimal(EXACT.scaleb(Decimal(-cents if scaled < 0 else cents), -2))


def _need_count(arg, name):
    if arg is None or not arg.isdigit():
        raise TabulaError("%s needs a whole number argument, got %r" % (name, arg))
    return int(arg)


def _need_decimal_arg(arg, name):
    number = None if arg is None else to_decimal(arg)
    if number is None:
        raise TabulaError("%s needs a number argument, got %r" % (name, arg))
    return number


def _no_arg(name, arg):
    if arg is not None:
        raise TabulaError("%s takes no argument, got %r" % (name, arg))


def _need_text(arg, name):
    if arg is None:
        raise TabulaError("%s needs an argument" % name)
    return arg


# --- the table -----------------------------------------------------------------------------------------------

class Table:
    """Column names and rows of strings. `source` names where it came from, for messages."""

    def __init__(self, columns, rows, source="<table>"):
        self.columns = list(columns)
        self.rows = [list(r) for r in rows]
        self.source = source

    def __len__(self):
        return len(self.rows)

    def index(self, name):
        """Position of a column; TabulaError when there is none."""
        try:
            return self.columns.index(name)
        except ValueError:
            raise TabulaError("%s: no column %r (columns: %s)" % (self.source, name, ", ".join(self.columns)))

    def column(self, name):
        at = self.index(name)
        return [row[at] for row in self.rows]

    def dicts(self):
        return [dict(zip(self.columns, row)) for row in self.rows]

    def with_rows(self, rows, columns=None):
        return Table(self.columns if columns is None else columns, rows, self.source)


def parse_text(text, source):
    """CSV text into a Table. Blank lines are ignored; every row must have as many fields as the header."""
    if text.startswith("﻿"):
        text = text[1:]
    reader = csv.reader(io.StringIO(text, newline=""))
    columns, rows = None, []
    try:
        for fields in reader:
            if not fields:
                continue
            if columns is None:
                for name in fields:
                    if not name.strip():
                        raise TabulaError("%s: line %d: empty column name" % (source, reader.line_num))
                if len(set(fields)) != len(fields):
                    raise TabulaError("%s: line %d: duplicate column name" % (source, reader.line_num))
                columns = fields
                continue
            if len(fields) != len(columns):
                raise TabulaError("%s: line %d: expected %d fields, found %d"
                                  % (source, reader.line_num, len(columns), len(fields)))
            rows.append(fields)
    except csv.Error as exc:
        raise TabulaError("%s: line %d: %s" % (source, reader.line_num, exc))
    if columns is None:
        raise TabulaError("%s: no header line" % source)
    return Table(columns, rows, source)


def load(path):
    """Read a CSV file (UTF-8, optional byte order mark, LF or CRLF) into a Table."""
    try:
        with open(path, "rb") as fh:
            raw = fh.read()
    except OSError as exc:
        raise TabulaError("%s: cannot read: %s" % (path, exc.strerror or exc))
    try:
        text = raw.decode("utf-8")
    except UnicodeDecodeError:
        raise TabulaError("%s: not valid UTF-8" % path)
    return parse_text(text, path)


# --- output --------------------------------------------------------------------------------------------------

def render_text(table):
    cells = [table.columns] + table.rows
    widths = [max(len(row[i]) for row in cells) for i in range(len(table.columns))]
    lines = ["  ".join(cell.ljust(width) for cell, width in zip(row, widths)).rstrip() for row in cells]
    return "\n".join(lines) + "\n"


def render_csv(table):
    out = io.StringIO()
    writer = csv.writer(out, lineterminator="\n")
    writer.writerow(table.columns)
    writer.writerows(table.rows)
    return out.getvalue()


def render_json(table):
    return json.dumps(table.dicts(), ensure_ascii=False) + "\n"


RENDERERS = {"text": render_text, "csv": render_csv, "json": render_json}


def render(table, fmt="text"):
    return RENDERERS[fmt](table)


"""The two kinds of failure a command can end in."""


class TabulaError(Exception):
    """A mistake in a file or in what was asked for; the command line ends with exit status 1."""


class UsageError(Exception):
    """A command line that is not shaped right; the command line ends with exit status 2."""
"""tabula: small tools for CSV tables."""
from .engine import Table, load, main, render
from .errors import TabulaError, UsageError

__all__ = ["Table", "TabulaError", "UsageError", "load", "main", "render"]
__version__ = "0.3.0"
import sys

from .engine import main

sys.exit(main())

}


def parse_spec(spec):
    """`name` or `name:arg` into (function, arg); the argument is everything after the first colon."""
    name, _, arg = spec.partition(":")
    if name not in TRANSFORMS:
        raise TabulaError("unknown transform %r" % name)
    return TRANSFORMS[name], (arg if ":" in spec else None)


def apply_transforms(value, specs):
    for fn, arg in specs:
        value = fn(value, arg)
    return value


# --- commands ------------------------------------------------------------------------------------------------

def _need_args(args, count, usage):
    if len(args) != count:
        raise UsageError("usage: %s %s" % (PROG, usage))


def cmd_show(args, opts):
    _need_args(args, 1, "show FILE")
    return load(args[0])


def cmd_head(args, opts):
    _need_args(args, 2, "head FILE N")
    if not args[1].isdigit():
        raise UsageError("head: N must be a whole number, got %r" % args[1])
    table = load(args[0])
    return table.with_rows(table.rows[:int(args[1])])


def cmd_cols(args, opts):
    _need_args(args, 1, "cols FILE")
    table = load(args[0])
    return Table(["position", "column"], [[str(i + 1), name] for i, name in enumerate(table.columns)], table.source)


def cmd_apply(args, opts):
    if len(args) < 3:
        raise UsageError("usage: %s apply FILE COLUMN TRANSFORM..." % PROG)
    table = load(args[0])
    at = table.index(args[1])
    specs = [parse_spec(s) for s in args[2:]]
    rows = []
    for number, row in enumerate(table.rows, 1):
        row = list(row)
        try:
            row[at] = apply_transforms(row[at], specs)
        except TabulaError as exc:
            raise TabulaError("%s: row %d: %s" % (table.source, number, exc))
        rows.append(row)
    return table.with_rows(rows)


def _need_min_args(args, count, usage):
    if len(args) < count:
        raise UsageError("usage: %s %s" % (PROG, usage))


SORT_MODIFIERS = ("num", "desc")


def _sort_key(spec):
    """`COLUMN[:num][:desc]` into (column, numeric, descending)."""
    name, *modifiers = spec.split(":")
    if not name:
        raise UsageError("sort: no column name in %r" % spec)
    for modifier in modifiers:
        if modifier not in SORT_MODIFIERS:
            raise UsageError("sort: unknown modifier %r in %r (use num or desc)" % (modifier, spec))
    if len(set(modifiers)) != len(modifiers):
        raise UsageError("sort: a modifier is given twice in %r" % spec)
    return name, "num" in modifiers, "desc" in modifiers


def cmd_sort(args, opts):
    _need_min_args(args, 2, "sort FILE KEY...")
    keys = [_sort_key(spec) for spec in args[1:]]
    table = load(args[0])
    keys = [(table.index(name), numeric, desc) for name, numeric, desc in keys]
    values = [[cell_number(table, n, at) if numeric else row[at] for at, numeric, _ in keys]
              for n, row in enumerate(table.rows)]
    order = list(range(len(table.rows)))
    for k in range(len(keys) - 1, -1, -1):  # one stable sort per key, the last key first
        order.sort(key=lambda n: values[n][k], reverse=keys[k][2])
    return table.with_rows([table.rows[n] for n in order])


# longest first, so that where two operators start at the same place the longer one wins
FILTER_OPERATORS = ("==", "!=", ">=", "<=", ">", "<", "~")


def _condition(arg):
    """`COLUMN OP VALUE` into (column, operator, value): the first operator in the argument, the longer at a tie."""
    for at in range(len(arg)):
        for op in FILTER_OPERATORS:
            if arg.startswith(op, at):
                if at == 0:
                    raise UsageError("filter: no column name in %r" % arg)
                return arg[:at], op, arg[at + len(op):]
    raise UsageError("filter: no operator (== != >= <= > < ~) in %r" % arg)


def _holds(cell, op, value, number):
    if op == "~":
        return value.lower() in cell.lower()
    left = to_decimal(cell) if number is not None else None
    if left is not None:
        cell, value = left, number
    return {"==": cell == value, "!=": cell != value, ">=": cell >= value, "<=": cell <= value,
            ">": cell > value, "<": cell < value}[op]


def cmd_filter(args, opts):
    _need_min_args(args, 2, "filter FILE CONDITION...")
    conditions = [_condition(arg) for arg in args[1:]]
    table = load(args[0])
    conditions = [(table.index(name), op, value, to_decimal(value)) for name, op, value in conditions]
    return table.with_rows([row for row in table.rows
                            if all(_holds(row[at], op, value, number) for at, op, value, number in conditions)])


AGGREGATES = ("sum", "min", "max", "mean")


def _aggregate(spec):
    """`count` or `KIND:COLUMN` into (kind, column or None)."""
    kind, colon, column = spec.partition(":")
    if spec == "count":
        return kind, None
    if kind not in AGGREGATES or not colon or not column:
        raise UsageError("group: %r is not an aggregate (count, sum:COLUMN, min:COLUMN, max:COLUMN, mean:COLUMN)" % spec)
    return kind, column


def _unique_columns(columns, source):
    for name in columns:
        if columns.count(name) > 1:
            raise TabulaError("%s: the result would have the column %r twice" % (source, name))
    return columns


def cmd_group(args, opts):
    _need_min_args(args, 3, "group FILE BY AGGREGATE...")
    if len(set(args[2:])) != len(args[2:]):
        raise UsageError("group: an aggregate is given twice")
    aggregates = [_aggregate(spec) for spec in args[2:]]
    table = load(args[0])
    by = table.index(args[1])
    columns = [None if column is None else table.index(column) for _, column in aggregates]
    groups = {}  # value of BY -> row numbers, in the order each value first appears
    for n, row in enumerate(table.rows):
        groups.setdefault(row[by], []).append(n)
    wanted = sorted(set(columns) - {None})
    numbers = {at: [] for at in wanted}  # row by row, so the first bad cell in file order is the one reported
    for n in range(len(table.rows)):
        for at in wanted:
            numbers[at].append(cell_number(table, n, at))
    rows = []
    for value, members in groups.items():
        out = [value]
        for (kind, _), at in zip(aggregates, columns):
            if kind == "count":
                out.append(str(len(members)))
                continue
            found = [numbers[at][n] for n in members]
            if kind == "sum":
                out.append(fmt_decimal(exact_sum(found)))
            elif kind == "mean":
                out.append(fmt_2dp(exact_sum(found), len(found)))
            else:
                out.append(fmt_decimal((min if kind == "min" else max)(found)))
        rows.append(out)
    names = [args[1]] + [spec.replace(":", "_") for spec in args[2:]]
    return Table(_unique_columns(names, table.source), rows, table.source)


def cmd_join(args, opts):
    _need_args(args, 3, "join LEFT RIGHT KEY")
    left, right = load(args[0]), load(args[1])
    at_left, at_right = left.index(args[2]), right.index(args[2])
    kept = [i for i in range(len(right.columns)) if i != at_right]
    columns = left.columns + [right.columns[i] + "_right" if right.columns[i] in left.columns else right.columns[i]
                              for i in kept]
    matches = {}
    for row in right.rows:
        matches.setdefault(row[at_right], []).append([row[i] for i in kept])
    rows = []
    for row in left.rows:
        found = matches.get(row[at_left])
        if found:
            rows.extend(row + other for other in found)
        elif opts["kind"] == "left":
            rows.append(row + [""] * len(kept))
    return Table(_unique_columns(columns, left.source), rows, left.source)


def cmd_pivot(args, opts):
    _need_args(args, 4, "pivot FILE ROW COLUMN VALUE")
    if args[1] == args[2]:
        raise UsageError("pivot: ROW and COLUMN must be different columns, got %r twice" % args[1])
    table = load(args[0])
    at_row, at_col, at_value = table.index(args[1]), table.index(args[2]), table.index(args[3])
    heads, rows, sums = {}, {}, {}  # distinct COLUMN values and ROW values (first appearance order), the sums
    for n, row in enumerate(table.rows):
        head = row[at_col]
        if not head:
            raise TabulaError("%s: row %d: column %r: empty value" % (table.source, n + 1, args[2]))
        if head == args[1]:
            raise TabulaError("%s: row %d: column %r: %r is the name of the ROW column" % (table.source, n + 1, args[2], head))
        number = cell_number(table, n, at_value)
        heads[head] = rows[row[at_row]] = None
        key = (row[at_row], head)
        sums[key] = number if key not in sums else EXACT.add(sums[key], number)
    return Table([args[1]] + list(heads),
                 [[value] + [fmt_decimal(sums[(value, head)]) if (value, head) in sums else "0" for head in heads]
                  for value in rows], table.source)


def cmd_dedupe(args, opts):
    _need_min_args(args, 2, "dedupe FILE KEY...")
    table = load(args[0])
    keys = [table.index(name) for name in args[1:]]
    chosen = {}  # the values of the KEY columns -> the number of the row that stays
    for n, row in enumerate(table.rows):
        key = tuple(row[at] for at in keys)
        if opts["keep"] == "last" or key not in chosen:
            chosen[key] = n
    stay = set(chosen.values())
    return table.with_rows([row for n, row in enumerate(table.rows) if n in stay])


def cmd_stats(args, opts):
    _need_min_args(args, 2, "stats FILE COLUMN...")
    table = load(args[0])
    rows = []
    for name in args[1:]:
        at = table.index(name)
        found = sorted(cell_number(table, n, at) for n, row in enumerate(table.rows) if row[at].strip())
        if not found:
            rows.append([name, "0", "", "", "", ""])
            continue
        middle = len(found) // 2
        median = fmt_2dp(found[middle]) if len(found) % 2 else fmt_2dp(EXACT.add(found[middle - 1], found[middle]), 2)
        rows.append([name, str(len(found)), fmt_decimal(found[0]), fmt_decimal(found[-1]),
                     fmt_2dp(exact_sum(found), len(found)), median])
    return Table(["column", "count", "min", "max", "mean", "median"], rows, table.source)


COMMANDS = {
    "show": (cmd_show, "show FILE", "print a table"),
    "head": (cmd_head, "head FILE N", "the first N rows"),
    "cols": (cmd_cols, "cols FILE", "the column names, numbered"),
    "apply": (cmd_apply, "apply FILE COLUMN TRANSFORM...", "run transforms over one column"),
    "sort": (cmd_sort, "sort FILE KEY...", "sort the rows by one or more keys"),
    "filter": (cmd_filter, "filter FILE CONDITION...", "keep the rows where every condition holds"),
    "group": (cmd_group, "group FILE BY AGGREGATE...", "one row per value of BY, with aggregates"),
    "join": (cmd_join, "join LEFT RIGHT KEY", "join two files on a column"),
    "pivot": (cmd_pivot, "pivot FILE ROW COLUMN VALUE", "sum VALUE into a ROW by COLUMN grid"),
    "dedupe": (cmd_dedupe, "dedupe FILE KEY...", "drop rows with repeated key values"),
    "stats": (cmd_stats, "stats FILE COLUMN...", "count, min, max, mean and median of columns"),
}


# --- the command line ----------------------------------------------------------------------------------------

def usage_text():
    lines = ["usage: %s [%s] COMMAND ARGS..." % (PROG, "] [".join("--%s %s" % (n, "|".join(v)) for n, (v, _) in OPTIONS.items())),
             "", "commands:"]
    width = max(len(u) for _, u, _ in COMMANDS.values())
    for _, use, what in COMMANDS.values():
        lines.append("  %s  %s" % (use.ljust(width), what))
    return "\n".join(lines) + "\n"


def parse_args(argv):
    """(command, positional arguments, options) from the command line."""
    opts, rest, i = {name: default for name, (_, default) in OPTIONS.items()}, [], 0
    while i < len(argv):
        arg = argv[i]
        name, equals, value = arg[2:].partition("=") if arg.startswith("--") else (None, "", "")
        if arg in ("-h", "--help"):
            opts["help"] = True
        elif name in OPTIONS:
            if not equals:
                i += 1
                if i >= len(argv):
                    raise UsageError("--%s needs a value" % name)
                value = argv[i]
            allowed = OPTIONS[name][0]
            if value not in allowed:
                raise UsageError("--%s must be one of %s, got %r" % (name, ", ".join(allowed), value))
            opts[name] = value
        elif arg.startswith("-") and len(arg) > 1:
            raise UsageError("unknown option %s" % arg)
        else:
            rest.append(arg)
        i += 1
    if opts.get("help"):
        return None, rest, opts
    if not rest:
        raise UsageError("no command given")
    if rest[0] not in COMMANDS:
        raise UsageError("unknown command %r" % rest[0])
    return rest[0], rest[1:], opts


def _drop_stdout():
    """Point standard output at the null device, so that the buffered text left behind cannot fail again at exit."""
    try:
        os.dup2(os.open(os.devnull, os.O_WRONLY), sys.stdout.fileno())
    except (OSError, ValueError, AttributeError):
        pass


def main(argv=None):
    argv = sys.argv[1:] if argv is None else list(argv)
    try:
        name, args, opts = parse_args(argv)
        if name is None:
            sys.stdout.write(usage_text())
            return 0
        table = COMMANDS[name][0](args, opts)
        sys.stdout.write(render(table, opts["format"]))
        sys.stdout.flush()
        return 0
    except UsageError as exc:
        print("%s: %s" % (PROG, exc), file=sys.stderr)
        return 2
    except TabulaError as exc:
        print("%s: %s" % (PROG, exc), file=sys.stderr)
        return 1
    except BrokenPipeError:
        _drop_stdout()
        return 0
    except OSError as exc:  # standard output that cannot be written (a full disk, say)
        _drop_stdout()
        print("%s: cannot write the result: %s" % (PROG, exc.strerror or exc), file=sys.stderr)
        return 1

